"use strict";(self.webpackChunkpsj_docs=self.webpackChunkpsj_docs||[]).push([[95589],{38513:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>i,contentTitle:()=>o,default:()=>u,frontMatter:()=>l,metadata:()=>s,toc:()=>c});var a=n(74848),r=n(28453);const l={title:"Advanced sample 3 - Highlight Assemble Faces",id:"table-advanced-sample-3",sidebar_label:"AS-3 Highlight Assemble Faces",description:"The example demonstrates how a table highlight Assemble Faces in model."},o=void 0,s={id:"tutorials/basic/table-advanced-sample-3",title:"Advanced sample 3 - Highlight Assemble Faces",description:"The example demonstrates how a table highlight Assemble Faces in model.",source:"@site/docs/tutorials/basic/Table_advanced_sample_3.md",sourceDirName:"tutorials/basic",slug:"/tutorials/basic/table-advanced-sample-3",permalink:"/docs/5.1.0/tutorials/basic/table-advanced-sample-3",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{title:"Advanced sample 3 - Highlight Assemble Faces",id:"table-advanced-sample-3",sidebar_label:"AS-3 Highlight Assemble Faces",description:"The example demonstrates how a table highlight Assemble Faces in model."},sidebar:"intro",previous:{title:"AS-2 Set cell alignment and check input value data type",permalink:"/docs/5.1.0/tutorials/basic/table-advanced-sample-2"},next:{title:"AS-4 Highlight Contact Faces",permalink:"/docs/5.1.0/tutorials/basic/table-advanced-sample-4"}},i={},c=[{value:"\ud83c\udfaf Introduction",id:"-introduction",level:2},{value:"\ud83d\udcd6 Tutorial",id:"-tutorial",level:2}];function d(e){const t={code:"code",h2:"h2",img:"img",li:"li",ol:"ol",p:"p",pre:"pre",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.h2,{id:"-introduction",children:"\ud83c\udfaf Introduction"}),"\n",(0,a.jsx)(t.p,{children:"In this tutorial, you'll learn how a table highlight Assemble Face in model:"}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsx)(t.li,{children:"Get groups from model and fill group names and IDs into table."}),"\n",(0,a.jsx)(t.li,{children:"If selects group name, JPT gets information of assemble faces and associated part, then highlights the assemble faces and sets transparency of parts."}),"\n",(0,a.jsx)(t.li,{children:"If selects group ID, JPT gets information of assemble faces and associated part, then highlights the assemble faces and sets transparency of parts."}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"Advanced sample 3",src:n(77473).A+"",width:"763",height:"543"})}),"\n",(0,a.jsx)(t.h2,{id:"-tutorial",children:"\ud83d\udcd6 Tutorial"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-psj",metastring:"showLineNumbers",children:'# Encoding for Japanese\r\n# coding: cp932\r\n\r\nfrom pyjdg import *\r\n\r\nJPT.Exec(\'CreateCube([0, 0, 0], [0.01, 0.01, 0.01], [10, 10, 10], "Cube_1", 7105764, 0:0)\')\r\nJPT.Exec(\'CreateCube([0.01, 0, 0], [0.01, 0.01, 0.01], [10, 10, 10], "Cube_2", 6409934, 0:0)\')\r\nJPT.Exec(\'CreateCube([0.02, 0, 0], [0.01, 0.01, 0.01], [10, 10, 10], "Cube_3", 13259210, 0:0)\')\r\nJPT.Exec(\'AssembleFaceMatingStep([], [], [3:1, 3:2, 3:3], 0.0001)\')\r\nJPT.Exec(\'AssembleFaceEx([49, 24, 50, 75], 0.0001, 0, 0)\')\r\nJPT.ViewFitToModel()\r\n\r\ndef on_click_set_info_cell(dlg):\r\n    """\r\n    Executes to get Group information, returns and sets Group Name/ID to table cell\r\n        Parameters:\r\n            No direct parameters, but requires the Groups in Group Tree must exit\r\n        Returns:\r\n            Sets Name of Group to the first column (col=0)\r\n            Sets ID of Group to the second column (col=1)\r\n    """\r\n    JPT.ClearLog()\r\n    listGroups = JPT.GetAllGroups()\r\n    for i in range(listGroups.sizeVec()):\r\n        group = listGroups[i]\r\n        dlg.set_cell_value(name="Table1",row=i,col=0,value=group.name)\r\n        dlg.set_cell_value(name="Table1",row=i,col=1,value=str(group.id))\r\n\r\ndef associated_part(selection):\r\n    """\r\n    Gets the associated Parts that face belong to, returns and sets transparency for those associated Parts\r\n        Parameters:\r\n            All selected Faces(vector)\r\n        Returns:\r\n            Sets transparency to be 10% for the associated Parts that Face belong to\r\n    """\r\n    all_bodies = JPT.GetAllParts()\r\n    for i in range(all_bodies.sizeVec()):\r\n        all_bodies[i].transparency = 100\r\n    associate_body = JPT.GetEntitiesByAssociation(JPT.DItemType.FACE, JPT.AssociateType.AS_BODY, int(selection[0].id))\r\n    for i in range(associate_body.sizeVec()):\r\n        JPT.SelectionByID(JPT.DItemType.BODY, associate_body[i].id, JPT.BoolType.TRUE_VAL)\r\n    selected_body = JPT.GetSelectedParts()\r\n    for i in range(selected_body.sizeVec()):\r\n        selected_body[i].transparency = 10\r\n    JPT.ClearAllSelection()\r\n\r\n\r\ndef select_face_in_group_by_name(group_name):\r\n    """\r\n    Get Group\'s Name from the cell, returns the entity Face of Group\r\n        Parameters:\r\n            Group Name(string): Name of the Group in the first column of the table (col=0)\r\n        Returns:\r\n            Selects the Face entity of Group\r\n    """\r\n    groups = JPT.GetEntitiesByName(JPT.DTableType.DTABLE_GROUP, group_name, 1)\r\n    if groups.sizeVec() > 0:\r\n        if groups[0].targets.sizeVec() > 0:\r\n            for entity in groups[0].targets:\r\n                JPT.SelectionByID(JPT.DItemType.FACE, entity.id, JPT.BoolType.TRUE_VAL)\r\n                selected_face = JPT.GetAllSelected()\r\n                associated_part(selected_face)\r\n                JPT.SelectionByID(JPT.DItemType.FACE, entity.id, JPT.BoolType.TRUE_VAL)\r\n\r\ndef select_face_in_group_by_id(group_id):\r\n    """\r\n    Get Group\'s ID from the cell, returns the entity Face of Group\r\n        Parameters:\r\n            Group ID(int): ID of the Group in the second column of the table (col=1)\r\n        Returns:\r\n            Selects the Face entity of Group\r\n    """\r\n    group_entity = JPT.GetEntitiesByID(JPT.DItemType.GROUP,int(group_id))\r\n    if group_entity.sizeVec() > 0:\r\n        if group_entity[0].targets.sizeVec() > 0:\r\n            for entity in group_entity[0].targets:\r\n                JPT.SelectionByID(JPT.DItemType.FACE, entity.id, JPT.BoolType.TRUE_VAL)\r\n                selected_face = JPT.GetAllSelected()\r\n                associated_part(selected_face)\r\n                JPT.SelectionByID(JPT.DItemType.FACE, entity.id, JPT.BoolType.TRUE_VAL)\r\n\r\ndef on_sel_change(dlg,name,target_cell):\r\n    """\r\n    Takes the value of cell, returns the View and highlights the Face\r\n        Parameters:\r\n            dlg: Dialog\r\n            name(string): Name of the Table\r\n            target_cell(object): TableCellID object specifying the location of cell in table\r\n        Returns:\r\n            Sets View that shows the target Face\r\n        Note:\r\n            This function calls the 2 functions: select_face_in_group_by_name & select_face_in_group_by_id\r\n    """\r\n    JPT.ClearAllSelection()\r\n    target_cell = dlg.get_table_sel_cell(name="Table1")\r\n    target_name = dlg.get_cell_value(name="Table1",row=target_cell[0].row_number,col=target_cell[0].col_number)\r\n    target_id = dlg.get_cell_value(name="Table1",row=target_cell[0].row_number,col=target_cell[0].col_number)\r\n    if target_cell[0].col_number==0:\r\n        select_face_in_group_by_name(target_name)\r\n    elif target_cell[0].col_number==1:\r\n        select_face_in_group_by_id(target_id)\r\n    JPT.ViewFitToModel()\r\n\r\ndef main():\r\n    dlg=JDGCreator(title="Dialog",resizable=True,validation=True)\r\n    dlg.add_layout(name="Layout1",orientation=orientation.vertical,layout="Window")\r\n    dlg.add_table(name="Table1",rows=5,columns=["Name","Index"],layout="Window",width=260,height=260)\r\n    dlg.add_label(name="Label3",text="1. Select the \'GetGroup\' Button",layout="Layout1")\r\n    dlg.add_label(name="Label4",text="2. Select the cell",layout="Layout1")\r\n    dlg.add_hlayout(name="footer",layout="Window")\r\n    dlg.add_space(orientation="horizontal",layout="footer")\r\n    dlg.add_button(name="GetGroup",text="GetGroup",width=70,height=30,layout="footer")\r\n    dlg.add_button(name="ButtonOk",text="Ok",layout="footer")\r\n    dlg.add_button(name="ButtonCancel",text="Cancel",layout="footer")\r\n    dlg.add_space(orientation="horizontal",layout="footer")\r\n    dlg.generate_window()\r\n    dlg.on_button_clicked(name="GetGroup",callfunc=on_click_set_info_cell)\r\n    dlg.on_table_sel_changed(name="Table1",callfunc=on_sel_change)\r\n\r\nif __name__==\'__main__\':\r\n    main()\n'})})]})}function u(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},77473:(e,t,n)=>{n.d(t,{A:()=>a});const a=n.p+"assets/images/advanced_sample_3_V5-14a3b1b3489472d310e1cab62fb9ec70.png"},28453:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>s});var a=n(96540);const r={},l=a.createContext(r);function o(e){const t=a.useContext(l);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),a.createElement(l.Provider,{value:t},e.children)}}}]);